<template><Card class="s45-manager"><template v-if="!$route.params.id"><h2>评价管理</h2><p class="intro">保留居民原文字、图片和星级，只能按独立监管权限留原因屏蔽或恢复。</p><Alert v-if="summary" type="info" show-icon>{{summary.label}} · 公开评价 {{summary.visibleCount}} 条 · 单星样本 {{summary.ratedCount}} 条<p>{{summary.basis}}</p></Alert><Form inline class="query"><FormItem label="星级"><Select v-model="star" clearable style="width:140px"><Option v-for="v in [1,2,3,4,5]" :key="v" :value="String(v)">{{v}} 星</Option></Select></FormItem><FormItem label="展示状态"><Select v-model="status" clearable style="width:160px"><Option value="OPEN">公开</Option><Option value="CLOSE">已屏蔽</Option></Select></FormItem><Button @click="filter">应用评价筛选</Button></Form><RecordList endpoint="/evaluations" :dated="false" :params="{star,status}" :columns="columns" :refresh-key="revision" @open="open"/></template><template v-else><Button @click="back">返回评价列表</Button><Button :loading="loading" @click="load">重新读取</Button><Alert v-if="error" type="error" show-icon>{{error}}</Alert><OperationRecovery :name="'evaluation:'+$route.params.id" :revision="revision" @recovered="load"/><template v-if="detail"><h2>{{detail.goodsName}}</h2><section class="detail-section"><dl class="facts"><div class="fact"><dt>原订单</dt><dd>{{detail.orderSn||'历史关联待解释'}}</dd></div><div class="fact"><dt>店铺</dt><dd>{{detail.storeName}}</dd></div><div class="fact"><dt>居民</dt><dd>{{detail.memberName}}</dd></div><div class="fact"><dt>单星</dt><dd>{{detail.star==null?'历史无单星':detail.star+' 星'}}</dd></div><div class="fact"><dt>提交时间</dt><dd>{{date(detail.createdAt)}}</dd></div><div class="fact"><dt>展示状态</dt><dd>{{detail.status==='OPEN'?'公开展示':'已屏蔽'}}</dd></div></dl><h3>原文字与图片</h3><p style="white-space:pre-wrap">{{detail.content||'未填写文字评价'}}</p><Evidence :ids="detail.files||[]"/></section><Form v-if="detail.canModerate" class="detail-section" label-position="top"><h3>{{detail.status==='OPEN'?'屏蔽评价':'恢复公开展示'}}</h3><FormItem label="监管原因 *"><Input v-model="reason" type="textarea" :maxlength="500" :disabled="busy" placeholder="填写本次展示状态调整的原因"/></FormItem><Button type="primary" :loading="busy" :disabled="pending" @click="moderate">{{detail.status==='OPEN'?'屏蔽此评价':'恢复此评价'}}</Button><p class="meta">屏蔽会排除公开均分与单星样本；恢复重新纳入。原内容、原星级和旧 grade 保留。</p></Form><h3>监管历史</h3><div v-for="(row,index) in detail.history" :key="index" class="history"><p>{{row.reason}}</p><p class="meta">{{date(row.at)}}</p></div></template></template></Card></template>
<script>
import RecordList from './components/RecordList.vue';import OperationRecovery from './components/OperationRecovery.vue';import Evidence from './components/Evidence.vue';import {s45Read,s45Commands} from '@/api/stage45';import {managerSession} from '@/libs/manager-session';import {date} from './presentation.cjs';
export default{components:{RecordList,OperationRecovery,Evidence},data(){return{star:this.$route.query.star||'',status:this.$route.query.status||'',summary:null,detail:null,reason:'',loading:false,busy:false,error:'',ticket:0,revision:0,columns:[{title:'商品',key:'goodsName',minWidth:220},{title:'店铺',key:'storeName',minWidth:170},{title:'居民',key:'memberName',minWidth:110},{title:'单星',minWidth:120,render:(h,{row})=>h('span',row.star==null?'历史无单星':row.star+' 星')},{title:'原文字',minWidth:270,render:(h,{row})=>h('span',row.content||'未填写文字评价')},{title:'公开状态',minWidth:120,render:(h,{row})=>h('span',row.status==='OPEN'?'公开':'已屏蔽')},{title:'提交时间',minWidth:190,render:(h,{row})=>h('span',date(row.createdAt))}]}},computed:{pending(){this.revision;return s45Commands.pending('evaluation:'+this.$route.params.id)}},watch:{'$route.params.id':{handler(){this.ticket++;this.detail=null;this.reason='';this.load()},immediate:true}},beforeDestroy(){this.ticket++;this.detail=null},methods:{date,async load(){const ticket=++this.ticket,owner=managerSession.snapshot();this.loading=true;this.error='';try{const id=this.$route.params.id,v=await s45Read(id?'/evaluations/'+id:'/evaluation-summary');if(ticket===this.ticket&&managerSession.sameSession(owner)){if(id)this.detail=v;else this.summary=v}}catch(e){if(ticket===this.ticket){this.detail=null;this.summary=null;this.error=e.message}}finally{if(ticket===this.ticket)this.loading=false}},filter(){this.$router.replace({path:'/s45/evaluations',query:{...this.$route.query,star:this.star,status:this.status,page:'1'}}).catch(()=>{});this.revision++;this.load()},open(row){this.$router.push({path:'/s45/evaluations/'+row.id,query:{...this.$route.query,star:this.star,status:this.status}})},back(){this.$router.push({path:'/s45/evaluations',query:this.$route.query})},moderate(){if(this.reason.trim().length<2){this.error='请填写至少2字的监管原因。';return}this.$Modal.confirm({title:this.detail.status==='OPEN'?'屏蔽评价':'恢复评价',content:'仅调整公开展示状态，保留居民原内容及单星。',onOk:async()=>{this.busy=true;this.error='';try{await s45Commands.run('evaluation:'+this.detail.id,'/evaluations/'+this.detail.id+'/moderate',{expectedVersion:this.detail.version,status:this.detail.status==='OPEN'?'CLOSE':'OPEN',reason:this.reason.trim()});this.reason='';this.load()}catch(e){this.error=e.message}finally{this.revision++;this.busy=false}}})}}};
</script><style lang="scss">@import './stage45.scss';</style>
